def readout(deltas: dict[str, dict[str, dict]], dropped: dict[str, set]) -> dict:
    """Per matched set: the rule on the tail delta (read sets; P-train reported only), with the
    changed-span delta's match beside it, reported only."""
    out = {}
    for para, err in {**READ_SETS, **REPORTED_ONLY}.items():
        if para not in deltas or err not in deltas:
            continue
        kept = {pid: v for pid, v in deltas[para].items() if pid not in dropped.get(para, set())}
        row = match([v["tail"] for v in deltas[err].values()], [v["tail"] for v in kept.values()])
        span = match([v["span"] for v in deltas[err].values()], [v["span"] for v in kept.values()])
        row["changed_span_only"] = span
        row["measures_disagree"] = span["passes"] != row["passes"]
        row["gated"] = para in READ_SETS
        out[para] = row
    out["all_read_sets_pass"] = all(out[s]["passes"] for s in READ_SETS if s in out)
    return out

/// Per check type metrics for `outcomes` against `gold`, in a stable order (grounded,
/// reasoning, knowledge). Gold claims without a label are not scored; a check type with
/// no labelled claim has no row. An outcome for a claim not in the gold set is ignored.
pub fn metrics(gold: &[Claim], outcomes: &[Outcome]) -> Vec<CheckMetrics> {
    let said: HashMap<&str, VerdictKind> = outcomes
        .iter()
        .map(|o| (o.claim_id.as_str(), o.verdict))
        .collect();
    [
        CheckType::Grounded,
        CheckType::Reasoning,
        CheckType::Knowledge,
    ]
    .into_iter()
    .filter_map(|ct| {
        let rows: Vec<&Claim> = gold
            .iter()
            .filter(|c| c.check_type == ct && c.label.is_some())
            .collect();
        (!rows.is_empty()).then(|| row(ct, &rows, &said))
    })
    .collect()
}

def parse_muse(text: str) -> dict:
    """muse-glimmer replies in plain text (format constraints empty its replies), ending in two
    lines: VERDICT and GRAMMATICAL. A trailing <|eot|> is stripped."""
    text = text.replace("<|eot|>", "").strip()
    verdict = re.findall(r"^\s*VERDICT:\s*(wrong|not wrong|unsure)\s*$", text, flags=re.I | re.M)
    grammar = re.findall(r"^\s*GRAMMATICAL:\s*(yes|no)\s*$", text, flags=re.I | re.M)
    if not verdict or not grammar:
        return {"outcome": "unparsed", "reasoning": text}
    return {
        "outcome": verdict[-1].lower(),
        "grammatical": grammar[-1].lower() == "yes",
        "reasoning": text.rsplit("VERDICT:", 1)[0].strip(),
    }

def seeded_sample(ids: list[str], fraction: float, seed: int = 0) -> set[str]:
    """A seeded random `fraction` of `ids` (at least one when there are any), independent of order."""
    pool = sorted(ids)
    random.Random(seed).shuffle(pool)
    return set(pool[: max(1, round(fraction * len(pool)))] if pool else [])

